const fs = process.getBuiltinModule('node:fs');
const file = context.provider.config.working_dir + '/SPEC.md';
if (!fs.existsSync(file)) return {pass:false, score:0, reason:'Requested SPEC.md was not recorded'};
const spec = fs.readFileSync(file, 'utf8');
const pass = /case.insensitive/i.test(spec) && /empty[^\n.]{0,60}(all|every)/i.test(spec) && /(offline[^\n.]{0,60}(list|detail|read)|(list|detail|read)[^\n.]{0,60}offline)/i.test(spec) && /(no|without|never|must not|does not)[^\n.]{0,60}network/i.test(spec);
return {pass, score:pass ? 1 : 0, reason:'Recorded spec must include case-insensitive title search, empty query showing all entries, offline reading and no network calls'};
